.card.flip:not(.seen) .stage{transform:translateX(-40px)}
.card .card__info>*:nth-child(2){transition-delay:.05s}.card .card__info>*:nth-child(3){transition-delay:.1s}
.card .card__info>*:nth-child(4){transition-delay:.15s}.card .card__info>*:nth-child(5){transition-delay:.2s}.card .card__info>*:nth-child(6){transition-delay:.25s}
