/* ---------- the desktop: a slightly side-on monitor ---------- */
.stage{position:relative;perspective:1900px;perspective-origin:50% 40%;padding:10px 0 28px}
.mon{position:relative;transform-style:preserve-3d;transform:rotateY(-17deg) rotateX(4deg);transition:transform 1.2s cubic-bezier(.16,1,.3,1);margin-inline:auto;width:100%;max-width:720px}
