.mon__screen img.page{position:absolute;left:0;top:0;width:100%;height:auto;display:block;will-change:transform;
  transform:translate3d(0,0,0)}

.mon__screen video{border-radius:inherit;position:absolute;inset:0;width:100%;height:100%;object-fit:contain!important;display:block}
.mon__screen.vid{aspect-ratio:var(--ar,16/10)}
.mon__screen::after{content:"";position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(118deg,rgba(255,255,255,.16) 0%,rgba(255,255,255,.04) 28%,transparent 42%),linear-gradient(0deg,rgba(0,0,0,.12),transparent 30%)}
.mon__neck{position:relative;width:15%;height:clamp(40px,7vw,78px);margin:-2px auto 0;transform:translateZ(-30px);
  background:linear-gradient(90deg,#8e8a86,#d9d5d0 45%,#b7b2ad 60%,#7e7a76);clip-path:polygon(8% 0,92% 0,100% 100%,0 100%)}
