  font:600 clamp(2rem,9.5vw,2.9rem)/1.06 'Onest',ui-sans-serif,system-ui,sans-serif;letter-spacing:-.03em;text-align:left;cursor:pointer;
  opacity:0;transform:translateY(1.1rem);transition:opacity .5s ease,transform .66s cubic-bezier(.16,1,.3,1),color .25s ease}
