.backd{order:-2;flex:none;display:inline-flex;align-items:center;gap:.5rem;height:2.75rem;padding:0 1.1rem 0 .85rem;
  border:1px solid rgba(var(--fg-rgb),.14);border-radius:999px;background:rgba(var(--fg-rgb),.05);color:var(--fg);
  font:500 .9375rem/1 'Onest',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;text-decoration:none;cursor:pointer;white-space:nowrap;
  opacity:0;transform:translateX(-.5rem);transition:opacity .35s ease,transform .45s cubic-bezier(.16,1,.3,1),background .25s ease,border-color .25s ease}
.backd.show{opacity:1;transform:none}
.backd svg{width:1.05rem;height:1.05rem;transition:transform .35s cubic-bezier(.16,1,.3,1)}
@media (hover:hover){.backd:hover{background:rgba(var(--fg-rgb),.1);border-color:rgba(var(--fg-rgb),.26)}.backd:hover svg{transform:translateX(-3px)}}
.backd:focus-visible{outline:2px solid #C4B0B0;outline-offset:3px}
/* phones keep the words on both pills; on the very narrowest screens they just get a little smaller */
@media (max-width:359.98px){.backd,.rn__menu{font-size:.8125rem}.backd{padding:0 .85rem 0 .7rem}.rn__menu{padding:0 .85rem}}
/* the leftover top row above each room's title, and the gap under the intro */
.top{display:none!important}
.intro{padding-bottom:clamp(28px,4vw,44px)!important}
.rn__in{min-width:0}
.rn nav{min-width:0}

.ck{position:fixed;left:50%;bottom:max(1rem,env(safe-area-inset-bottom));z-index:90;transform:translateX(-50%);width:min(34rem,calc(100% - 2rem));
  display:flex;align-items:center;gap:1rem;padding:.9rem .9rem .9rem 1.2rem;border-radius:1.25rem;background:#1A1818;color:#E8E4E0;
  box-shadow:0 18px 40px -16px rgba(0,0,0,.55),0 0 0 1px rgba(232,228,224,.12);font:400 .875rem/1.45 'Onest',ui-sans-serif,system-ui,sans-serif}
.ck[hidden]{display:none}
.ck p{margin:0;flex:1}.ck a{color:inherit}
.ck div{display:flex;gap:.5rem;flex:none}
.ck button{height:2.5rem;padding:0 1rem;border-radius:999px;border:1px solid rgba(232,228,224,.25);background:none;color:inherit;font:inherit;font-size:.8125rem;font-weight:600;line-height:1;cursor:pointer}
.ck button[data-ck="yes"]{background:#E8E4E0;color:#1A1818;border-color:transparent}
@media (max-width:539.98px){.ck{flex-direction:column;align-items:stretch}.ck div button{flex:1}}

