  /* ————— Owner-private HUD ————— */
  function ownerPrivateDoc() {
    const task = (title, desc, templateId) => `
      <div class="nl-task">
        <div class="nl-task-meta"><div class="nl-task-title">${title}</div><div class="nl-task-desc">${desc}</div></div>
