            <button type="button" class="nl-icon-btn nl-tap" id="nl-pop-close" aria-label="Close">${CLOSE_SVG}</button>
          </div>
          <div class="nl-popover-body">
            ${task(
              "SEO / GEO audit",
              "Check that Google and AI assistants can find and read your site.",
